style.css:
@-moz-document domain("teams.microsoft.com") {
/* General background for Teams */
  body {
    background-color: #001f3f !important; /* Dark blue */
    color: #ffffff !important; /* White text */
  }

  /* Header styling */
  .header, .top-bar {
    background-color: #003366 !important; /* Darker blue for the header */
    color: #ffffff !important;
  }

  /* Chat messages background */
  .chat-message, .chat-content {
    background-color: #00264d !important; /* Blue background for chat bubbles */
    color: #d1e8ff !important; /* Light blue text */
  }

  /* Sidebar (Teams list) */
  .sidebar, .teams-sidebar {
    background-color: #001f3f !important; /* Dark blue for sidebar */
    color: #ffffff !important;
  }

  /* Links */
  a {
    color: #66b3ff !important; /* Bright blue for links */
    text-decoration: none;
  }

  a:hover {
    color: #3399ff !important; /* Slightly darker blue on hover */
  }

  /* Buttons */
  button {
    background-color: #003366 !important; /* Dark blue */
    color: #ffffff !important;
    border-radius: 5px;
  }

  button:hover {
    background-color: #00509e !important; /* Brighter blue on hover */
  }

  /* Inputs (search bar, etc.) */
  input, textarea {
    background-color: #00264d !important; /* Dark blue background */
    color: #ffffff !important;
    border: 1px solid #004080 !important;
  }

  input:focus, textarea:focus {
    border-color: #3399ff !important; /* Bright blue on focus */
  }

  /* Footer or system messages */
  footer, .footer {
    background-color: #001f3f !important;
    color: #d1e8ff !important;
  }
}
